<script setup lang="ts">
import QueryPanel from './QueryPanel.vue';
import QueryField from './QueryField.vue';
import ListPanel from './ListPanel.vue';
import {computed,onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import { Plus, Search } from 'lucide-vue-next';import {api} from '../api';import {post,patch,errorText,dateText} from '../saas';import {useSessionStore} from '../stores/session';import ProvincePageState from './ProvincePageState.vue';
const session=useSessionStore(),canWrite=computed(()=>session.user?.accountLevel==='PROVINCE'&&session.user.permissions.includes('system:organization:update'));const rows=ref<any[]>([]),options=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),page=ref(1),total=ref(0),q=ref(''),status=ref(''),kind=ref(''),workspaceId=ref(''),dialog=ref(false),editId=ref('');const kinds:Record<string,string>={VEHICLE:'保障车辆',STAFF:'保障人员',SITE:'场站',ENERGY:'补能',REPAIR:'维修'};const statuses:Record<string,string>={AVAILABLE:'可调用',BUSY:'使用中',UNAVAILABLE:'不可调用'};const form=reactive({workspaceId:'',name:'',kind:'VEHICLE',status:'AVAILABLE',capacity:1,contactName:'',contactPhone:'',conditions:''});
async function load(){loading.value=true;error.value='';try{if(!options.value.length)options.value=(await api<any>('/oversight/options')).workspaces;const p=new URLSearchParams({page:String(page.value),pageSize:'20'});for(const[k,v]of Object.entries({q:q.value.trim(),status:status.value,kind:kind.value,workspaceId:workspaceId.value}))if(v)p.set(k,v);const r=await api<any>(`/oversight/resources?${p}`);rows.value=r.items;total.value=r.total}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function search(){page.value=1;load()}function open(row?:any){editId.value=row?.id??'';Object.assign(form,{workspaceId:row?.workspaceId??options.value[0]?.id??'',name:row?.name??'',kind:row?.kind??'VEHICLE',status:row?.status??'AVAILABLE',capacity:row?.capacity??1,contactName:row?.contactName??'',contactPhone:row?.contactPhone??'',conditions:row?.conditions??''});dialog.value=true}
async function save(){if(!form.workspaceId||form.name.trim().length<2)return ElMessage.warning('请选择城市并填写资源名称');saving.value=true;try{if(editId.value)await patch(`/oversight/resources/${editId.value}`,{...form});else await post('/oversight/resources',{...form});dialog.value=false;ElMessage.success('资源信息已保存');await load()}catch(e){ElMessage.error(errorText(e))}finally{saving.value=false}}
onMounted(async()=>{try{options.value=(await api<any>('/oversight/options')).workspaces}catch(e){error.value=errorText(e);return}await load()});

function resetQueryFilters() {
  q.value = '';
  workspaceId.value = '';
  kind.value = '';
  status.value = '';
  page.value = 1;
  search();
}
</script>
<template><section class="province-page"><QueryPanel :loading="loading" @search="search" @reset="resetQueryFilters">
<QueryField label="关键词" keyword><el-input aria-label="关键词" v-model="q" :prefix-icon="Search" clearable placeholder="搜索资源名称或联系人" /></QueryField>
<QueryField label="城市"><el-select aria-label="城市" v-model="workspaceId" clearable placeholder="全部城市" @change="search"><el-option v-for="o in options" :key="o.id" :label="o.cityName" :value="o.id"/></el-select></QueryField>
<QueryField label="类型"><el-select aria-label="类型" v-model="kind" clearable placeholder="全部类型" @change="search"><el-option v-for="(label,key) in kinds" :key="key" :label="label" :value="key"/></el-select></QueryField>
<QueryField label="状态"><el-select aria-label="状态" v-model="status" clearable placeholder="全部状态" @change="search"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select></QueryField>
</QueryPanel>
<ListPanel title="应急资源列表" :total="error ? undefined : (total)">
<template #actions><el-button v-if="canWrite" type="primary" :icon="Plus" @click="open()">新增资源</el-button></template>
<ProvincePageState :error="error" :loading="loading" @retry="load"><el-table :data="rows" empty-text="暂无符合条件的应急资源"><el-table-column label="资源名称" prop="name" min-width="210"/><el-table-column label="城市" min-width="100"><template #default="{row}">{{row.cityName??row.workspace?.cityName}}</template></el-table-column><el-table-column label="类型" width="100"><template #default="{row}">{{kinds[row.kind]??row.kind}}</template></el-table-column><el-table-column label="可保障数量" prop="capacity" width="110"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='AVAILABLE'?'success':row.status==='BUSY'?'warning':'info'">{{statuses[row.status]??row.status}}</el-tag></template></el-table-column><el-table-column label="联系人" width="120" prop="contactName"/><el-table-column label="联系电话" min-width="145" prop="contactPhone"/><el-table-column label="使用条件" min-width="200" prop="conditions" show-overflow-tooltip/><el-table-column v-if="canWrite" label="操作" width="80" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">维护</el-button></template></el-table-column></el-table><div class="province-pagination"><span>共 {{total}} 项资源</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div></ProvincePageState>
</ListPanel>
<el-dialog class="province-dialog" v-model="dialog" :title="editId?'维护应急资源':'新增应急资源'" width="650px" destroy-on-close><el-form label-position="top"><div class="province-form-grid"><el-form-item label="所属城市" required><el-select v-model="form.workspaceId"><el-option v-for="o in options" :key="o.id" :label="o.cityName" :value="o.id"/></el-select></el-form-item><el-form-item label="资源类型" required><el-select v-model="form.kind"><el-option v-for="(label,key) in kinds" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="资源名称" required class="full"><el-input v-model="form.name" maxlength="120"/></el-form-item><el-form-item label="可保障数量" required><el-input-number v-model="form.capacity" :min="1" :max="1000000"/></el-form-item><el-form-item label="资源状态"><el-select v-model="form.status"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName" maxlength="40"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone" maxlength="30"/></el-form-item><el-form-item label="保障条件" class="full"><el-input v-model="form.conditions" type="textarea" :rows="3" maxlength="2000"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存资源</el-button></template></el-dialog></section></template>
